package com.fasterxml.jackson.databind.ser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.ser.PropertyFilter;
import com.fasterxml.jackson.databind.ser.std.MapSerializer;
import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class AnyGetterWriter_getAndFilter_TriageGen0Test {

    private AnyGetterWriter writer;

    @Mock
    private PropertyAccessor _accessor;

    @Mock
    private JsonGenerator gen;

    @Mock
    private SerializerProvider provider;

    @Mock
    private PropertyFilter filter;

    @Mock
    private MapSerializer _mapSerializer;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        // AnyGetterWriter is typically instantiated via internal Jackson mechanisms, 
        // so we use reflection to instantiate and inject private fields for testing.
        writer = (AnyGetterWriter) Class.forName("com.fasterxml.jackson.databind.ser.AnyGetterWriter")
                .getDeclaredConstructor(PropertyAccessor.class)
                .newInstance(_accessor);

        setField(writer, "_mapSerializer", _mapSerializer);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testGetAndFilter_ValueIsNull() throws Exception {
        Object bean = new Object();
        when(_accessor.getValue(bean)).thenReturn(null);

        writer.getAndFilter(bean, gen, provider, filter);

        verifyNoInteractions(gen);
        verifyNoInteractions(filter);
        verify(_mapSerializer, never()).serializeFilteredFields(any(), any(), any(), any(), any());
    }

    @Test(expected = JsonMappingException.class)
    public void testGetAndFilter_ValueIsNotMap() throws Exception {
        Object bean = new Object();
        String notAMap = "I am a string";
        when(_accessor.getValue(bean)).thenReturn(notAMap);
        when(_accessor.getName()).thenReturn("testGetter");

        try {
            writer.getAndFilter(bean, gen, provider, filter);
        } catch (JsonMappingException e) {
            assert(e.getMessage().contains("not java.util.Map"));
            throw e;
        }
    }

    @Test
    public void testGetAndFilter_WithMapSerializer() throws Exception {
        Object bean = new Object();
        Map<String, Object> map = new HashMap<>();
        map.put("key", "value");

        when(_accessor.getValue(bean)).thenReturn(map);
        // _mapSerializer is set in setUp

        writer.getAndFilter(bean, gen, provider, filter);

        verify(_mapSerializer).serializeFilteredFields(eq(map), eq(gen), eq(provider), eq(filter), eq(null));
    }

    @Test
    public void testGetAndFilter_WithoutMapSerializer() throws Exception {
        // Reset to null map serializer
        setField(writer, "_mapSerializer", null);

        Object bean = new Object();
        Map<String, Object> map = new HashMap<>();
        when(_accessor.getValue(bean)).thenReturn(map);

        // This hits the "not sure how custom handler would do it" comment branch
        // Since the method ends there, we just verify it doesn't throw and doesn't call serializer
        writer.getAndFilter(bean, gen, provider, filter);

        verifyNoInteractions(_mapSerializer);
    }
}

/**
 * Mocking the PropertyAccessor since it's an internal interface/abstract class 
 * used by AnyGetterWriter.
 */
interface PropertyAccessor {
    Object getValue(Object bean) throws Exception;
    String getName();
}
